Buffer a{1024};
Buffer b = a;      // 逐成员拷贝：b.data 和 a.data 指向同一块内存
// 作用域结束，b 先析构 delete[] 一次，a 再析构 delete[] 第二次 —— 崩溃

struct Buffer {
    size_t size;
    int* data;          // 裸指针：逐成员拷贝只复制地址

    explicit Buffer(size_t n) : size(n), data(new int[n]{}) {}
    ~Buffer() { delete[] data; }
};

Buffer(const Buffer& other)
    : size(other.size), data(new int[other.size]) {
    std::copy(other.data, other.data + size, data);
}

Buffer& operator=(const Buffer& other) {
    if (this == &other) { return *this; }   // 少了这行，下一步就把源毁了
    int* fresh = new int[other.size];       // 先分配，后释放
    std::copy(other.data, other.data + other.size, fresh);
    delete[] data;
    data = fresh;
    size = other.size;
    return *this;
}

Buffer make();          // 按值返回

Buffer a{4};
Buffer&& r1 = make();   // 可以：纯右值
Buffer&& r2 = a;        // 编译错误：a 是左值
Buffer&& r3 = std::move(a);  // 可以：std::move 把它转成将亡值

// 注意 r1 本身是有名字的变量，所以 r1 是左值——
// 「右值引用类型的变量」和「右值」是两回事。

void sink(std::vector<int>&& v) {   // sink 接管 v 的所有权
    store_somewhere(std::move(v));
    // 之后不再使用 v：它已经处于被移动状态
}

std::vector<int> data{1, 2, 3};
sink(data);              // 编译错误——挡住了「我没想搬走它」的情况
sink(std::move(data));   // 明确表态：data 之后我不用了

template<typename T>
class Vector {
public:
    Vector(Vector&& a) noexcept : elem{a.elem}, sz{a.sz} {
        a.elem = nullptr;   // 源置空：它的析构不能再释放这块内存
        a.sz = 0;
    }
    Vector& operator=(Vector&& a) noexcept {
        if (&a != this) {
            delete[] elem;
            elem = a.elem; sz = a.sz;
            a.elem = nullptr; a.sz = 0;
        }
        return *this;
    }
    // ...
};

// std::move 的效果等价于一次类型转换
static_cast<Buffer&&>(a)

// 所以这一行什么都没搬：没有人接收这个右值
std::move(a);

// 搬运发生在这里——右值被移动构造接住了
Buffer b = std::move(a);

class Handle {
public:
    ~Handle();                                   // 有自定义析构
    Handle(const Handle&);                       // 那这五个就都要表态
    Handle& operator=(const Handle&);
    Handle(Handle&&) noexcept;
    Handle& operator=(Handle&&) noexcept;
    // 需要默认构造就再加一个；不需要就 = delete
};

template<class F, class... Args>
decltype(auto) invoke(F&& f, Args&&... args) {
    return std::forward<F>(f)(std::forward<Args>(args)...);
}
